import{_ as e}from"./Voyager3-DUi7U2xc.js";import{_ as o,c as n,h as s,a as r}from"./app-BJ-I1O-M.js";const i={};function a(l,t){return r(),n("div",null,t[0]||(t[0]=[s('<img src="'+e+'" style="display:block;margin:0 auto;"><link rel="stylesheet" href="/css/font-style.css"><h2 id="introduce" tabindex="-1"><a class="header-anchor" href="#introduce"><span>Introduce</span></a></h2><p> 和 Meow 聊了两三天关于自己的私事。很感谢她能提出自己的见解，有很多地方都对我有不少启发，当然也有一些东西是我后来想到的。</p><p> 首先，我需要阐明的是，情感类问题涉及主观情绪，所以在很大程度上受个人和生长环境因素影响。这里并没有什么对错之分，但总体而言，我十分赞同 Meow 对我的评价，但又有些许地方我需要进行辩驳/补充（你提的问题有点多，我当时脑子有点跟不上，也来不及想）。</p><ol><li><p>Meow 批评我没有在情感上的主观性，比如缺少对自我需求的思考，我喜欢什么？需要什么？这是最致命也是最重要的。我觉得造成这个问题的原因是，貌似我本身就蔑视情感问题，压根没有在意过自己需要什么，比如说我直到现在都没有衣品，感觉穿什么无所谓，干净就好；或者我并不希望在一些认为是琐事上做决策（当然我认为感情也是一种琐事），还有吃饭不挑食有什么吃什么；更进一步来说我有种低欲望感，认为这些事都没有太大的意义和价值，比如我曾发表过为什么我们不直接打葡萄糖而是去纠结吃到这个问题，我是真的有考虑过……最后就是我如何看待无主观这个问题的，如果可以的话一切从简，有什么做什么，当然也可以有主观的思考，比如我需要什么，但这种问题我一般会放在感兴趣的地方，比如计算机。当然 <strong>我当时确实是应该直接表明自己的想法，没有推开她是我的问题，这点没什么可避讳的，我赞同Meow。</strong></p></li><li><p>底线问题，我需要澄清一下我的底线。第一，我不会平白无故答应别人，她磨了我两个月我才没法了答应，从 9 月一直磨到 11 月，最后她说“我愿意和你一起努力学习的”，我才答应，不是随随便便的（抱歉，我忘记说了，让你白白浪费那么长时间说我，但是我确实，我应该主观判断一下的，可惜啊，我没有火眼金睛）。<strong>赞同</strong></p></li><li><p>第二，有时候确实是没有自我的，更准确来说我不想在这些事上操太多心（如果有人帮我做抉择就好了，比如衣服选择，吃什么饭）<strong>补充</strong>，但是你提到的 <strong>“读了很多书，还是无法认识自己”</strong>，<strong>我很赞同</strong>，事实上我之所以闲的无聊看书，一方面是希望有所见识，另一方面是因为我需要了解自己，但 <strong>我至今不清楚我究竟如何才能与过去的自己和解，如何才能真正认识现在（仍在努力）</strong>。</p></li><li><p>关于前任，我对她的评价中肯，有过错也有优点，但这都不重要，重要的是我不在乎一个人是否外边好看，家境如何，我更在意她是谁，她内心有什么，她如何看待人/物。再简练些就是 <strong>我更注重一个人的内心</strong>，所以我希望她能和我聊的很来。我会在走神的时候去畅想，哦，这是我们的未来，当然也会因为一些事情感到懊恼痛苦，胡思乱想。这是解释“她有什么优点的”，我不喜欢她什么，但是“我愿意和你一起努力学习”对我的杀伤力很大，我正是需要这种同行的人……<strong>补充</strong></p></li><li><p>关于我没有什么喜欢她的，为什么却在意她给别的男生发照片？<strong>这个问题很古怪</strong>，或者说我应该指正这个问题的提问方式，“我不知道我喜欢她什么”和“她给别的男生发照片管我什么事”貌似并不能在一起问。我们代入她的视角来看会很好理解的。“她很喜欢一个男生，然后正在跟她喜欢的男生谈恋爱，却把自己的照片发给别的男生打趣”，你不觉得在她的视角来看这个问题是很诡异的么？或者说第一次高考吵架完后她就已经不爱我了，于是她才问心无愧的把照片发给其他男生？那她何必再缠着我呢……<strong>问题质疑</strong></p></li><li><p>再回到你说的“以自己的感受为主，喜欢一个人的特质…”，如果真的说我喜欢一个人需要有什么特质，那我希望是 <strong>博识的、平静的、直白的、自强不息的，她可以样貌不出众</strong>。<strong>赞同</strong></p></li><li><p>你提到的父母贪图儿女我不是很认同，这个需要看人，有的父母不行有的父母可以，但我承认大多数可能是这样子的，尤其是品行恶劣的（“如果父母家庭不和谐、精神不健康等等，孩子就会成为血包”）。<strong>补充</strong></p></li><li><p>最后是幼稚、热爱和坚持。我承认你说的是绝大多数的人在社会当中需要面对的现实问题。但纯粹的热爱和喜欢一个东西并不掺杂于爱情（三大件：爱情、事业、爱好）。我当然可以说，我喜欢计算机是纯粹的，它不包含任何其他的利益关系。最起码对于现在的我而言它是如此，我可以不用考虑产出，因为我在校…但当我出了社会，我可能就需要考虑这些东西了……但是，<strong>这个社会需要有理想主义者，他们需要去用自己的极端想法创造新的事物，这些想法可能听起来可笑，但是最终实现确实重磅级的（比如很有名的苹果的电容触摸屏）</strong>。至于热爱究竟能支撑多久，我不清楚，但最起码我应该放眼现在，做好每一天就好；<strong>热爱并非逃避现实的借口，恰恰相反，正是因为我们热爱，所以才不满足于现实，我们需要新的创新和改进错误，即使这个世界充满了现实矛盾</strong>。<strong>不认同/补充</strong></p></li></ol>',6)]))}const g=o(i,[["render",a]]),m=JSON.parse('{"path":"/posts/Meow.html","title":"深度对话——Meow 与我","lang":"en-US","frontmatter":{"title":"深度对话——Meow 与我","description":"深度对话——Meow 与我","date":"2026-03-08T00:00:00.000Z","timeline":true,"head":[["meta",{"name":"keywords","content":"深度对话——Meow 与我"}],["meta",{"name":"description","content":"深度对话——Meow 与我"}],["meta",{"name":"author","content":"RobinElysia"}]],"category":["RobinElysia"],"tag":["碎碎念"]},"headers":[{"level":2,"title":"Introduce","slug":"introduce","link":"#introduce","children":[]}],"git":{"updatedTime":1772905854000,"contributors":[{"name":"qwp_p","username":"","email":"qwp20060309@outlook.com","commits":1}],"changelog":[{"hash":"0e81f66b28ba600cf2f53c5cd5ce4243598efc05","time":1772905854000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"260307"}]},"filePathRelative":"posts/Meow.md","excerpt":"<img src=\\"/assets/img/MachineLearning/Voyager3.jpg\\" style=\\"display: block;margin: 0 auto;\\">\\n<link rel=\\"stylesheet\\" href=\\"/css/font-style.css\\">\\n<h2>Introduce</h2>\\n<p> 和 Meow 聊了两三天关于自己的私事。很感谢她能提出自己的见解，有很多地方都对我有不少启发，当然也有一些东西是我后来想到的。</p>\\n<p> 首先，我需要阐明的是，情感类问题涉及主观情绪，所以在很大程度上受个人和生长环境因素影响。这里并没有什么对错之分，但总体而言，我十分赞同 Meow 对我的评价，但又有些许地方我需要进行辩驳/补充（你提的问题有点多，我当时脑子有点跟不上，也来不及想）。</p>"}');export{g as comp,m as data};
